import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

# 5D shapes: (batch, channels, depth, height, width)
FRACTIONAL_MAXPOOL3D_BACKWARD_CONFIGS = [
    ((4, 3, 8, 32, 32), 2, (4, 16, 16)),
    ((8, 16, 8, 28, 28), 2, (4, 14, 14)),
    ((2, 4, 8, 20, 20), 2, (4, 10, 10)),
    ((1, 64, 8, 56, 56), 2, (4, 28, 28)),
    ((2, 8, 4, 16, 16), 2, (2, 8, 8)),
    ((2, 8, 8, 16, 20), 2, (4, 8, 10)),
]


@pytest.mark.fractional_max_pool3d_backward
@pytest.mark.parametrize(
    "shape, kernel_size, output_size", FRACTIONAL_MAXPOOL3D_BACKWARD_CONFIGS
)
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_accuracy_fractional_max_pool3d_backward(
    shape, kernel_size, output_size, dtype
):
    inp = torch.randn(shape, dtype=dtype, device=flag_gems.device, requires_grad=True)
    ref_inp = utils.to_reference(inp, True)

    N, C = shape[0], shape[1]
    # random_samples must match input dtype for torch.nn.functional
    random_samples = torch.rand(N, C, 3, dtype=dtype, device=flag_gems.device)
    ref_random_samples = random_samples.to(device=ref_inp.device, dtype=ref_inp.dtype)

    # Forward pass to get indices (use torch directly, forward is a separate PR)
    ref_out, ref_indices = torch.nn.functional.fractional_max_pool3d(
        ref_inp,
        kernel_size=kernel_size,
        output_size=output_size,
        return_indices=True,
        _random_samples=ref_random_samples,
    )

    res_out, res_indices = torch.nn.functional.fractional_max_pool3d(
        inp,
        kernel_size=kernel_size,
        output_size=output_size,
        return_indices=True,
        _random_samples=random_samples,
    )

    # Create grad_output
    grad_output = torch.randn_like(res_out)
    ref_grad_output = grad_output.to(device=ref_inp.device, dtype=ref_inp.dtype)

    # Backward pass
    ref_grad_input = torch.ops.aten.fractional_max_pool3d_backward(
        ref_grad_output,
        ref_inp,
        kernel_size,
        output_size,
        ref_indices,
    )

    res_grad_input = flag_gems.fractional_max_pool3d_backward(
        grad_output,
        inp,
        kernel_size=kernel_size,
        output_size=output_size,
        indices=res_indices,
    )

    utils.gems_assert_close(res_grad_input, ref_grad_input, dtype)
